"use client";
import { useState } from "react";
import { useRouter } from "next/navigation";
import axios from "axios";
import cookies from "js-cookie";

// Axios interceptor to attach the token to every request
axios.interceptors.request.use((config) => {
  const token = cookies.get("token");
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

export default function Login() {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const router = useRouter();

  const handleLogin = async (e) => {
    e.preventDefault();
    setError("");
    setSuccessMessage("");

    // Validate inputs
    if (!email || !password) {
      setError("Email et mot de passe sont obligatoires");
      return;
    }

    try {
      // Send login request to the backend
      const { data } = await axios.post("http://localhost:5000/api/login", { email, password });
      
      // Store the token in a cookie
      cookies.set("token", data.token, { 
        secure: process.env.NODE_ENV === "production", 
        sameSite: "strict", 
        expires: 1 // Expires in 1 day
      });
      
      // Set success message
      setSuccessMessage(data.message || "Connexion réussie !");

      // Redirect based on role
      setTimeout(() => {
        switch (data.user.role) {
          case "etudiant":
            router.push(`/users/Etinterface/${data.user.user_id}`);
            break;
            case "tuteur":
              router.push(`/users/Tutinterface/${data.user.user_id}`);
            break;
             case "encadrant":
            router.push(`/users/EncadrantInterface/${data.user.user_id}`);
            break;  
          default:
            router.push("/dashboard");
        }
      }, 2000); // Redirect after 2 seconds
    } catch (err) {
      // Handle errors
      setError(err.response?.data?.message || "Identifiants incorrects");
    }
  };

  return (
    <div className="flex min-h-screen items-center justify-center bg-gray-100 text-gray-800">
      <div className="bg-white p-10 rounded-lg shadow-lg w-96">
        <h2 className="text-4xl font-bold mb-6 text-center text-blue-900">Bienvenue</h2>
        {error && <p className="text-red-500 text-center mb-4">{error}</p>}
        {successMessage && <p className="text-green-500 text-center mb-4">{successMessage}</p>}
        
        <form onSubmit={handleLogin} className="space-y-4">
          <input
            type="email"
            placeholder="Email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            className="block w-full p-4 border rounded-lg focus:ring focus:ring-blue-300 focus:outline-none"
            required
          />

          <input
            type="password"
            placeholder="Mot de passe"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className="block w-full p-4 border rounded-lg focus:ring focus:ring-blue-300 focus:outline-none"
            required
          />

          <button
            type="submit"
            className="w-full bg-blue-700 text-white py-3 px-4 rounded-lg hover:bg-blue-900 transition duration-300"
          >
            Se connecter
          </button>
        </form>
      </div>
    </div>
  );
}